 */
export default function PageTransition({ children }) {
  const overlayVariants = {
    initial: {
      scaleY: 1
    },
    animate: {
      scaleY: 0,
      transition: {
        duration: 0.65,
        ease: [0.76, 0, 0.24, 1], // easeInOutExpo
