        className="w-full"
      >
        {children}
      </motion.div>
    </div>
  );
}

import React, { useState, useEffect, useRef } from "react";
import { gsap } from "gsap";
import Plasma from "../ui/Plasma";

/**
 * Preloader ΓÇö cinematic intro, single smooth upward exit wipe.
 */
export default function Preloader({ onComplete }) {
  const [progress, setProgress] = useState(0);
  const containerRef   = useRef(null);
  const line1Ref       = useRef(null);
  const line2Ref       = useRef(null);
  const progressBarRef = useRef(null);
  const numberRef      = useRef(null);
  const glowRef        = useRef(null);
  const gridRef        = useRef(null);

  useEffect(() => {
    document.body.style.overflow = "hidden";

    const ctx = gsap.context(() => {
      /* ΓöÇΓöÇ Initial states ΓöÇΓöÇ */
      gsap.set([line1Ref.current, line2Ref.current], { y: "110%", opacity: 0 });
      gsap.set(progressBarRef.current, { scaleX: 0 });
      gsap.set(glowRef.current, { opacity: 0 });

      const exitAnimation = () => {
        // Fade grid before wipe so it doesn't flash
        gsap.to(gridRef.current, { opacity: 0, duration: 0.3, ease: "power2.in" });
        gsap.to(containerRef.current, {
          yPercent: -100,
          duration: 1.1,
          ease: "power4.inOut",
          delay: 0.1,
          onComplete: () => {
            document.body.style.overflow = "";
            if (onComplete) onComplete();
          },
        });
      };

      /* ΓöÇΓöÇ Main loading timeline ΓöÇΓöÇ */
      const tl = gsap.timeline({ onComplete: exitAnimation });

      // Ambient glow
      tl.to(glowRef.current, {
        opacity: 1,
        duration: 0.7,
        ease: "power2.out",
      }, 0);

      // Line 1 ΓÇö DANISH
      tl.to(line1Ref.current, {
        y: "0%",
        opacity: 1,
        duration: 1.0,
        ease: "power4.out",
      }, 0.1);

      // Line 2 ΓÇö KHAN
      tl.to(line2Ref.current, {
        y: "0%",
        opacity: 1,
        duration: 1.0,
        ease: "power4.out",
      }, 0.22);

      // Progress counter 0 ΓåÆ 100
      const counter = { v: 0 };
      tl.to(counter, {
        v: 100,
        duration: 1.8,
        ease: "power2.inOut",
        onUpdate: () => setProgress(Math.floor(counter.v)),
      }, 0.1);

      // Progress bar fill
      tl.to(progressBarRef.current, {
        scaleX: 1,
        duration: 1.8,
        ease: "power2.inOut",
      }, 0.1);

      // Tiny hold so user sees 100% for a beat, then exit fires immediately
      tl.to({}, { duration: 0.15 });
    }, containerRef);

    return () => {
      ctx.revert();
      document.body.style.overflow = "";
    };
  }, [onComplete]);

  return (
    <div
      ref={containerRef}
      className="fixed inset-0 z-[999999] select-none overflow-hidden"
      style={{ background: "#080809" }}
    >
      {/* WebGL Plasma Background - Ambient Gold Glow */}
      <div className="absolute inset-0 z-0 opacity-25 pointer-events-none">
        <Plasma
          color="#EADBC8"
          speed={0.15}
          scale={1.5}
          opacity={0.3}
          mouseInteractive={false}
        />
      </div>
      {/* Ambient gold glow */}
      <div
        ref={glowRef}
        className="absolute inset-0 pointer-events-none"
        style={{
          background:
            "radial-gradient(ellipse 55% 35% at 50% 50%, rgba(197,168,128,0.10) 0%, transparent 70%)",
        }}
      />

      {/* Subtle grid overlay */}
      <div
